from pathlib import Path
import json
P=Path(__file__).resolve().parent
font='@font-face{font-family:Inter;src:url(assets/inter-latin-700-normal.woff2);font-weight:700}@font-face{font-family:Inter;src:url(assets/inter-latin-400-normal.woff2);font-weight:400}'
concepts=[('Transformer','Attention + feedforward','blocks'),('Language model','Score the next token','tokens'),('Tokenization','Text becomes identifiers','split'),('Embeddings','Learned vector representations','dots'),('Context window','A finite token budget','window'),('Prompt design','Task + context + constraints','prompt'),('Vector search','Find nearby representations','search'),('RAG','Retrieve, then generate','rag'),('Fine-tuning','Adapt with training examples','train'),('RLHF','Learn from preference signals','reward'),('Quantization','Lower precision, less storage','bits'),('Evaluations','Test against real requirements','eval'),('Agent loop','Act, observe, revise','loop'),('Tool calling','Validate, execute, return','tool'),('MCP','A shared connection protocol','network'),('Guardrails','Check inputs, actions, outputs','guard')]
colors=['#32499d','#167a5c','#b84926','#874093']
def rect(x,y,w,h,txt,fill='white'):
 return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="6" fill="{fill}" stroke="currentColor"/><text x="{x+w/2}" y="{y+h/2+4}" text-anchor="middle">{txt}</text>'
def line(x,y,a,b):return f'<path d="M{x} {y} L{a} {b}" fill="none" stroke="currentColor" stroke-width="1.7" marker-end="url(#arrow)"/>'
def diagram(k):
 if k=='blocks':return rect(25,15,170,80,'')+rect(40,32,140,23,'attention')+rect(40,65,140,23,'feedforward')+line(110,125,110,100)+rect(40,128,140,22,'token representations')
 if k in ['tokens','split']:
  return rect(15,15,190,30,'The sky is blue')+line(110,50,110,75)+''.join(rect(7+i*54,82,49,30,t) for i,t in enumerate(['The','sky','is','blue']))+f'<text x="110" y="145" text-anchor="middle">{"predict the next token" if k=="tokens" else "IDs depend on the tokenizer"}</text>'
 if k in ['dots','search']:
  return '<path d="M20 15V140H205" fill="none" stroke="currentColor"/>'+''.join(f'<circle class="dot" cx="{x}" cy="{y}" r="5" fill="currentColor"/><text x="{x+8}" y="{y+4}">{t}</text>' for x,y,t in [(50,40,'cat'),(75,58,'dog'),(130,110,'bus'),(150,130,'car')])+('<circle class="ring" cx="63" cy="50" r="30" fill="none" stroke="currentColor" stroke-dasharray="3 3"/>' if k=='search' else '')
 if k=='window':return rect(33,35,156,56,'')+''.join(rect(7+i*26,45,22,36,'', '#a9dcca' if 1<i<7 else 'white') for i in range(8))+'<text x="110" y="125" text-anchor="middle">Keep relevant context inside.</text>'
 if k=='prompt':return rect(15,20,135,105,'')+''.join(f'<text x="30" y="{45+i*25}">{t}</text>' for i,t in enumerate(['Task','Evidence','Output rules']))+line(155,72,195,72)+'<circle cx="205" cy="72" r="12" fill="currentColor"/>'
 if k in ['rag','tool','guard']:
  labels={'rag':['Docs','Retrieve','Answer'],'tool':['Model','Tool','Result'],'guard':['Input','Checks','Output']}[k]
  return ''.join(rect(5+i*74,45,62,47,t) for i,t in enumerate(labels))+line(68,68,77,68)+line(142,68,151,68)+'<text x="110" y="135" text-anchor="middle">'+{'rag':'Check evidence and citations.','tool':'Application controls execution.','guard':'Enforce permissions in code.'}[k]+'</text>'
 if k=='train':return rect(7,25,65,65,'Data')+line(75,58,95,58)+rect(100,25,110,65,'Model + adapter')+'<text x="110" y="132" text-anchor="middle">Evaluate held-out examples.</text>'
 if k=='reward':return rect(10,20,85,35,'Answer A')+rect(125,20,85,35,'Answer B')+line(55,60,105,90)+line(165,60,115,90)+rect(65,95,90,35,'Preference')
 if k=='bits':return '<text x="15" y="28">16-bit weights</text>'+''.join(f'<rect x="{10+i*12}" y="40" width="9" height="27" fill="currentColor"/>' for i in range(16))+'<text x="15" y="102">4-bit weights (illustrative)</text>'+''.join(f'<rect x="{10+i*12}" y="114" width="9" height="27" fill="currentColor"/>' for i in range(4))
 if k=='eval':return ''.join(rect(15,13+i*42,190,32,t) for i,t in enumerate(['Accuracy: measure','Latency: measure','Cost: measure']))
 if k=='loop':return '<circle cx="110" cy="78" r="48" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="4 3"/>'+rect(73,5,74,28,'Plan')+rect(138,65,74,28,'Act')+rect(73,125,74,28,'Observe')+rect(7,65,74,28,'Revise')
 return ''.join(line(40,y,180,z) for y in [30,75,120] for z in [30,75,120])+''.join(f'<circle cx="{x}" cy="{y}" r="13" fill="white" stroke="currentColor"/>' for x in [40,180] for y in [30,75,120])
body='<header><div>HOW MODERN AI SYSTEMS WORK</div><h1><em>16</em> concepts. One useful map.</h1></header><main>'
for i,(t,d,k) in enumerate(concepts):
 c=colors[i//4];body+=f'<section style="--c:{c}"><h2><span>{i+1:02}</span>{t}</h2><p>{d}</p><svg viewBox="0 0 220 160"><defs><marker id="arrow" markerWidth="4" markerHeight="4" refX="3" refY="2" orient="auto"><path d="M0 0L4 2L0 4" fill="currentColor"/></marker></defs><g class="draw">{diagram(k)}</g><circle class="moving" r="3" fill="currentColor"/></svg></section>'
body+='</main><footer><b>WITHHAMMAD</b><span>Save this map. Build one concept.</span><b>withhammad.com</b></footer>'
css=font+'*{box-sizing:border-box}body{margin:0;width:1080px;height:1350px;background:#fbfbfa;color:#26355b;font-family:Inter;overflow:hidden}header{padding:45px 42px 24px}header div{font-size:18px;letter-spacing:2px}h1{font-size:49px;letter-spacing:-2px;margin:18px 0 0}h1 em{font-style:normal;color:#c5542f}main{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;padding:0 40px}section{height:260px;border:1.5px dashed var(--c);border-radius:16px;background:color-mix(in srgb,var(--c) 7%,white);color:var(--c);padding:16px 12px}h2{font-size:19px;margin:0;display:flex;gap:7px;align-items:center;white-space:nowrap}h2 span{background:var(--c);color:white;border-radius:5px;padding:6px 4px;font-size:14px}section p{font-size:13px;height:30px;margin:14px 0 8px;font-weight:700;line-height:1.3}svg{width:100%;height:145px;display:block}svg text{font:11px Inter;fill:currentColor}footer{margin:25px 42px;border-top:1px dashed #a1afc4;padding-top:22px;display:flex;justify-content:space-between;font-size:18px}'
script='window.__seek=(t)=>{document.querySelectorAll("section").forEach((e,i)=>{const q=(t%8)/8*2*Math.PI+i*.23;const d=e.querySelector(".draw");d.style.opacity=.9+.1*Math.cos(q);const m=e.querySelector(".moving");m.setAttribute("cx",110+85*Math.cos(q));m.setAttribute("cy",80+65*Math.sin(q));e.querySelectorAll(".dot").forEach((n,j)=>n.setAttribute("r",4+1.4*Math.sin(q+j)));});};window.__seek(0);'
(P/'07-ai-concepts.html').write_text(f'<!doctype html><html><head><meta charset="utf-8"><style>{css}</style></head><body>{body}<script>{script}</script></body></html>')
css=font+'''*{box-sizing:border-box}body{margin:0;width:1080px;height:1120px;overflow:hidden;background:#f4efd8;font-family:Inter;color:#2b241c}#scene{position:absolute;top:40px;left:0;width:1080px;height:1080px;background-image:url(assets/hype-strip.png);background-size:3240px 1080px}#model{position:absolute;left:448px;top:580px;width:190px;text-align:center;font-size:40px;font-weight:700;color:#312c23}#headline{position:absolute;top:35px;left:55px;right:55px;font-size:48px;text-align:center;font-weight:700;background:#f4efd8e8;padding:15px}#foot{position:absolute;bottom:25px;left:40px;right:40px;display:flex;justify-content:space-between;font-size:21px;font-weight:700;background:#f4efd8e8;padding:12px}'''
body='<div id="scene"></div><div id="model">GPT</div><div id="headline">The new-model hype cycle</div><div id="foot"><span>WITHHAMMAD</span><span>Test the model on your actual work.</span></div>'
script='''window.__seek=(t)=>{const p=t%15.5,phase=Math.floor(p/5.1667),local=p%5.1667;const pose=local<1.9?0:local<3.45?1:2;document.querySelector('#scene').style.backgroundPosition=(-pose*1080)+'px 0';document.querySelector('#model').textContent=['GPT','Gemini','Claude'][phase%3];document.querySelector('#headline').textContent=local<1.9?'This changes everything!':local<3.45?'The best model. Ever.':'Wait… another model just dropped.';document.querySelector('#model').style.transform='scale('+(1+.025*Math.sin(local*3))+')';};window.__seek(0);'''
(P/'06-model-hype.html').write_text(f'<!doctype html><html><head><meta charset="utf-8"><style>{css}</style></head><body>{body}<script>{script}</script></body></html>')
print('Created 16-concept animation and 15.5s model hype loop')
